from __future__ import annotations


def _legacy_dashboard_html() -> str:
    return """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>StockWise Paper Portfolio</title>
<style>
:root{--bg:#07111f;--panel:#101e31;--line:#223650;--text:#edf5ff;--muted:#91a5bd;--green:#3ddc97;--red:#ff6b78;--blue:#6ea8fe}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#07111f,#0b1728);color:var(--text);font:14px Inter,system-ui,sans-serif}
main{max-width:1240px;margin:auto;padding:32px}header{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}h1{margin:0;font-size:30px}h2{font-size:16px;margin:0 0 14px}.sub,.muted{color:var(--muted)}
.badge{padding:7px 11px;border:1px solid #285d4b;border-radius:99px;color:var(--green);background:#102a27}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.card{background:rgba(16,30,49,.92);border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 10px 30px #0003}.metric{font-size:25px;font-weight:700;margin-top:7px}.wide{grid-column:span 2}.section{margin-top:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:600}.empty{padding:28px;text-align:center;color:var(--muted)}button{background:#193553;color:var(--text);border:1px solid #2c5278;border-radius:8px;padding:7px 10px;cursor:pointer}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:650}.positive{color:var(--green)}.negative{color:var(--red)}
@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}.wide{grid-column:span 2}}@media(max-width:520px){main{padding:18px}.grid{grid-template-columns:1fr}.wide{grid-column:span 1}header{display:block}.badge{display:inline-block;margin-top:12px}}
</style></head><body><main>
<header><div><h1>StockWise</h1><div class="sub">Five-agent forward paper portfolio</div></div><div class="badge">SIMULATED NEXT OPEN</div></header>
<div class="grid">
 <section class="card"><div class="muted">Portfolio equity</div><div id="equity" class="metric">—</div></section>
 <section class="card"><div class="muted">Total P&amp;L</div><div id="pnl" class="metric">—</div></section>
 <section class="card"><div class="muted">Realized P&amp;L</div><div id="realized" class="metric">—</div></section>
 <section class="card"><div class="muted">Cash</div><div id="cash" class="metric">—</div></section>
</div>
<div class="grid">
 <section class="card wide"><h2>Current positions</h2><div id="positions" class="empty">No executed positions yet.</div></section>
 <section class="card wide"><h2>Latest council decision</h2><div id="decision" class="empty">No frozen council decision yet.</div></section>
</div>
<section class="card section"><h2>Transaction history</h2><div id="trades" class="empty">No simulated fills yet.</div></section>
<p class="muted">Research simulation only. Prices and fills are modeled and are not brokerage executions.</p>
</main><script>
const money=v=>v==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v));
const tone=(el,v)=>{el.className='metric '+(Number(v)>=0?'positive':'negative')};
async function load(){
 const [o,d,t]=await Promise.all(['/dashboard/overview','/dashboard/decisions','/dashboard/trades'].map(u=>fetch(u).then(r=>r.json())));
 const p=o.portfolio;if(p){equity.textContent=money(p.equity);cash.textContent=money(p.cash);realized.textContent=money(p.realized_pnl);tone(realized,p.realized_pnl);const total=Number(p.equity)-1000;pnl.textContent=money(total);tone(pnl,total);
  const rows=Object.entries(p.positions||{}).map(([s,x])=>`<tr><td>${s}</td><td>${Number(x.quantity).toFixed(4)}</td><td>${money(x.average_cost)}</td><td>${money(x.mark)}</td><td class="${Number(x.unrealized_pnl)>=0?'positive':'negative'}">${money(x.unrealized_pnl)}</td></tr>`).join('');
  positions.innerHTML=rows?`<table><thead><tr><th>Stock</th><th>Shares</th><th>Avg. cost</th><th>Price</th><th>Unrealized P&amp;L</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No open positions.</div>';
 }
 if(d.length){const x=d[d.length-1].payload;const decisionData=x.decision||{};decision.innerHTML=`<p><b>${decisionData.decision_at||d[d.length-1].decision_date}</b></p><p>Selected: ${(decisionData.selected_symbols||[]).join(', ')||'none'}</p><details><summary>View complete agent discussion</summary><pre style="white-space:pre-wrap;color:var(--muted)">${(x.human_report_markdown||'').replaceAll('<','&lt;')}</pre></details>`;}
 if(t.length){trades.innerHTML=`<table><thead><tr><th>Time</th><th>Stock</th><th>Side</th><th>Quantity</th><th>Price</th><th>Status</th></tr></thead><tbody>${t.slice().reverse().map(x=>`<tr><td>${x.executed_at||x.occurred_at}</td><td>${x.symbol||'—'}</td><td>${x.side||'—'}</td><td>${x.quantity||'—'}</td><td>${money(x.price)}</td><td>${x.status}</td></tr>`).join('')}</tbody></table>`;}
}load().catch(e=>{document.querySelector('.sub').textContent='Dashboard data unavailable: '+e.message});
</script></body></html>"""


def dashboard_html() -> str:
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StockWise Research Console</title>
<style>
:root{--bg:#07101d;--panel:#101c2e;--line:#253a57;--text:#edf5ff;--muted:#91a8c4;--green:#51e6a1;--red:#ff7180;--blue:#75adff;--amber:#ffc966}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 0,#102748 0,transparent 30%),var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}button,a{font:inherit}main{max-width:1480px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}h1{margin:0;font-size:32px}h2{font-size:17px;margin:0}.sub,.muted{color:var(--muted)}.badge,.pill{display:inline-flex;border-radius:99px;padding:6px 10px;font-size:12px;font-weight:700}.badge,.pill.good{border:1px solid #2b634f;background:#102a25;color:var(--green)}.pill.warn{background:#3a2d14;color:var(--amber)}.pill.neutral{background:#1a2a40;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:linear-gradient(150deg,#142238,#0d192a);border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:0 16px 40px #0003}.label{color:var(--muted);font-size:13px}.metric{font-size:27px;font-weight:760;margin-top:7px}.positive{color:var(--green)!important}.negative{color:var(--red)!important}.layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(350px,.7fr);gap:16px;margin-top:16px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:15px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}tr[data-symbol]{cursor:pointer}tr[data-symbol]:hover{background:#1a2d47}.ticker{color:var(--blue);font-weight:800}.scroll{max-height:510px;overflow:auto}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.mini{background:#0b1728;border:1px solid var(--line);border-radius:11px;padding:11px}.mini b{display:block;font-size:20px;margin-top:4px}.notice{border-left:3px solid var(--amber);background:#32281455;padding:10px 12px;border-radius:6px;color:#f5d998;margin:12px 0}.tabs{display:flex;gap:7px}.tabs button{border:1px solid var(--line);background:#12223a;color:var(--muted);border-radius:9px;padding:8px 11px;cursor:pointer}.tabs button.active{color:var(--text);border-color:#4175b4;background:#193454}.bar{height:5px;background:#26384e;border-radius:4px;margin-top:5px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#4f8cff,var(--green))}.empty{padding:28px;text-align:center;color:var(--muted)}.drawer{position:fixed;inset:0;z-index:20;display:none;background:#020711aa;backdrop-filter:blur(5px)}.drawer.open{display:block}.panel{position:absolute;right:0;top:0;height:100%;width:min(760px,94vw);overflow:auto;background:#0c1728;border-left:1px solid var(--line);padding:28px;box-shadow:-24px 0 70px #0008}.close{float:right;position:sticky;top:0;border:1px solid var(--line);background:#172942;color:var(--text);border-radius:50%;width:36px;height:36px;cursor:pointer}.title{font-size:27px;margin:8px 0 3px}.thesis{font-size:16px;line-height:1.6;background:#122138;border:1px solid var(--line);border-radius:13px;padding:16px}.agents{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.agent,.source{background:#101e32;border:1px solid var(--line);border-radius:12px;padding:14px}.agent h4{margin:0 0 8px}.agent p,.agent li{line-height:1.5;color:#c4d3e6}.source{display:block;text-decoration:none;color:#cde0f7;margin:8px 0}.source:hover{border-color:var(--blue)}.source small{display:block;color:var(--muted);margin-top:5px}.footer{color:var(--muted);margin:18px 2px}@media(max-width:980px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}@media(max-width:620px){main{padding:16px}.agents{grid-template-columns:1fr}.hide{display:none}}
</style></head><body><main><header><div><h1>StockWise</h1><div class="sub">Five-agent research and forward paper portfolio</div></div><span id="dataStatus" class="badge">PAPER TRADING</span></header>
<section class="metrics"><div class="card"><div class="label">Portfolio equity</div><div id="equity" class="metric">--</div></div><div class="card"><div class="label">Total P&amp;L</div><div id="pnl" class="metric">--</div></div><div class="card"><div class="label">Realized P&amp;L</div><div id="realized" class="metric">--</div></div><div class="card"><div class="label">Available cash</div><div id="cash" class="metric">--</div></div></section>
<section class="layout"><div class="card"><div class="head"><div><h2>Current positions</h2><span class="muted">Click a stock for its council analysis</span></div><span id="positionCount" class="pill neutral">0 holdings</span></div><div id="positions" class="scroll empty">No positions yet.</div></div><div class="card"><div class="head"><div><h2>Latest council</h2><span id="decisionDate" class="muted">No decision</span></div><span class="pill good">CURRENT POLICY</span></div><div id="decisionSummary"></div></div></section>
<section class="card" style="margin-top:16px"><div class="head"><div><h2>Council ranking</h2><span class="muted">Unified score used for selection</span></div><div class="tabs"><button id="selectedTab" class="active">Selected 20</button><button id="allTab">All 50</button></div></div><div id="ranking" class="empty">No analysis available.</div></section>
<section class="card" style="margin-top:16px"><div class="head"><div><h2>Execution history</h2><span class="muted">Immutable simulated fills and rejected orders</span></div></div><div id="trades" class="empty">No fills yet.</div></section><p class="footer">Research simulation only. No brokerage orders are submitted.</p></main>
<aside id="drawer" class="drawer" aria-hidden="true"><div class="panel"><button id="closeDrawer" class="close" aria-label="Close analysis">X</button><div id="analysis"></div></div></aside>
<script>
const $=x=>document.getElementById(x),money=v=>v==null?'--':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),tone=(e,v)=>{e.className='metric '+(Number(v)>=0?'positive':'negative')};let council,showAll=false;
const roles={MARKET_TECHNICAL:'Market & technical',BUSINESS_FUNDAMENTALS:'Business quality',NEWS_FILINGS_CATALYSTS:'News & catalysts',RISK_SENTIMENT:'Risk & sentiment'};
function openStock(symbol){const c=council?.candidates.find(x=>x.packet.symbol===symbol);if(!c)return;const p=c.packet,s=c.synthesis,k=p.quantitative_features?.kronos_signal||{},chosen=council.selected_symbols.includes(symbol);const agents=c.contributions.map(a=>`<article class="agent"><h4>${esc(roles[a.role]||a.role)} <span class="pill neutral">${a.score}/100</span></h4><p>${esc(a.summary)}</p>${a.supporting_points?.length?`<b>Supporting points</b><ul>${a.supporting_points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${a.concerns?.length?`<b>Concerns</b><ul>${a.concerns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</article>`).join('');const sources=p.evidence.map(e=>e.source_url?`<a class="source" href="${esc(e.source_url)}" target="_blank" rel="noopener"><b>${esc(e.source)}</b><small>${esc(e.claim)}</small></a>`:`<div class="source"><b>${esc(e.source)}</b><small>${esc(e.claim)}</small></div>`).join('');$('analysis').innerHTML=`<span class="pill ${chosen?'good':'neutral'}">${chosen?'SELECTED':'NOT SELECTED'}</span><h2 class="title">${esc(p.symbol)} <span class="muted">${esc(p.company_name)}</span></h2><div class="muted">${esc(p.sector||'Sector unavailable')} · Rank ${council.candidates.indexOf(c)+1} · ${Number(c.adjusted_score).toFixed(2)}/100</div>${k.status==='UNRELIABLE'?'<div class="notice"><b>Kronos sanity guard active.</b> The absolute forecast was excluded from agent scoring; the upstream shortlist still used cross-sectional rank.</div>':''}<h3>Final synthesis</h3><p class="thesis">${esc(s.thesis)}</p><div class="summary"><div class="mini"><span class="label">Unified</span><b>${Number(c.adjusted_score).toFixed(2)}</b></div><div class="mini"><span class="label">Synthesis</span><b>${s.investment_score}</b></div><div class="mini"><span class="label">Agent range</span><b>${c.specialist_score_range??'--'}</b></div></div><h3>Agent contributions</h3><div class="agents">${agents}</div><h3 style="margin-top:22px">Evidence and source links</h3>${sources||'<p class="muted">No linked evidence.</p>'}`;$('drawer').classList.add('open');$('drawer').setAttribute('aria-hidden','false')}
function ranking(){if(!council)return;const data=council.candidates.filter(c=>showAll||council.selected_symbols.includes(c.packet.symbol));$('ranking').className='';$('ranking').innerHTML=`<table><thead><tr><th>#</th><th>Company</th><th>Score</th><th class="hide">Confidence</th><th>Status</th><th class="hide">Kronos</th></tr></thead><tbody>${data.map((c,i)=>{const chosen=council.selected_symbols.includes(c.packet.symbol),k=c.packet.quantitative_features?.kronos_signal||{};return `<tr data-symbol="${esc(c.packet.symbol)}"><td>${showAll?council.candidates.indexOf(c)+1:i+1}</td><td><span class="ticker">${esc(c.packet.symbol)}</span><br><small class="muted">${esc(c.packet.company_name)}</small></td><td>${Number(c.adjusted_score).toFixed(2)}<div class="bar"><i style="width:${c.adjusted_score}%"></i></div></td><td class="hide">${c.synthesis.confidence}%</td><td><span class="pill ${chosen?'good':'neutral'}">${chosen?'Selected':'Passed'}</span></td><td class="hide"><span class="pill ${k.status==='UNRELIABLE'?'warn':'good'}">${esc(k.status||'N/A')}</span></td></tr>`}).join('')}</tbody></table>`;document.querySelectorAll('#ranking tr[data-symbol]').forEach(r=>r.onclick=()=>openStock(r.dataset.symbol))}
async function load(){$('dataStatus').textContent='REFRESHING PRICES';let refreshError='';try{const r=await fetch('/dashboard/refresh-prices',{method:'POST'});if(!r.ok)throw Error(`HTTP ${r.status}`);const x=await r.json();if(x.status==='NO_UPDATE')refreshError='PRICE UPDATE UNAVAILABLE'}catch(e){refreshError='PRICE REFRESH FAILED'}const[o,d,t]=await Promise.all(['/dashboard/overview','/dashboard/decisions','/dashboard/trades'].map(u=>fetch(u).then(r=>r.json()))),p=o.portfolio;if(p){const stale=p.stale_symbols||[];$('dataStatus').textContent=refreshError|| (stale.length?`STALE: ${stale.join(', ')}`:`UPDATED ${new Date(p.prices_retrieved_at||p.occurred_at).toLocaleTimeString()}`);$('dataStatus').style.color=refreshError||stale.length?'var(--amber)':'var(--green)';$('equity').textContent=money(p.equity);$('cash').textContent=money(p.cash);$('realized').textContent=money(p.realized_pnl);tone($('realized'),p.realized_pnl);const total=Number(p.equity)-1000;$('pnl').textContent=money(total);tone($('pnl'),total);const ps=Object.entries(p.positions||{});$('positionCount').textContent=`${ps.length} holdings`;$('positions').className='scroll';$('positions').innerHTML=`<table><thead><tr><th>Stock</th><th>Shares</th><th>Avg. cost</th><th>Price</th><th>P&amp;L</th></tr></thead><tbody>${ps.map(([s,x])=>`<tr data-symbol="${esc(s)}"><td class="ticker">${esc(s)}</td><td>${Number(x.quantity).toFixed(4)}</td><td>${money(x.average_cost)}</td><td>${money(x.mark)}</td><td class="${Number(x.unrealized_pnl)>=0?'positive':'negative'}">${money(x.unrealized_pnl)}</td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('#positions tr[data-symbol]').forEach(r=>r.onclick=()=>openStock(r.dataset.symbol))}if(d.length){council=d[d.length-1].payload.decision;$('decisionDate').textContent=new Date(council.decision_at).toLocaleString();const bad=council.candidates.filter(c=>c.packet.quantitative_features?.kronos_signal?.status==='UNRELIABLE').length;$('decisionSummary').innerHTML=`<div class="summary"><div class="mini"><span class="label">Selected</span><b>${council.selected_symbols.length}/20</b></div><div class="mini"><span class="label">Reviewed</span><b>${council.candidates.length}</b></div><div class="mini"><span class="label">Eligible</span><b>${council.candidates.filter(c=>c.eligible).length}</b></div></div>${bad?`<div class="notice">Kronos sanity guard triggered for ${bad} candidates. Open a stock for details.</div>`:''}<p class="muted">Policy: ${esc(council.prompt_version)}</p>`;ranking()}if(t.length){$('trades').className='';$('trades').innerHTML=`<table><thead><tr><th>Time</th><th>Stock</th><th>Side</th><th>Quantity</th><th>Price</th><th>Status</th></tr></thead><tbody>${t.slice().reverse().map(x=>`<tr><td>${esc(x.executed_at||x.occurred_at)}</td><td class="ticker">${esc(x.symbol||'--')}</td><td>${esc(x.side||'--')}</td><td>${esc(x.quantity||'--')}</td><td>${money(x.price)}</td><td><span class="pill ${x.status==='FILLED'?'good':'warn'}">${esc(x.status)}</span></td></tr>`).join('')}</tbody></table>`}}
$('selectedTab').onclick=()=>{showAll=false;$('selectedTab').classList.add('active');$('allTab').classList.remove('active');ranking()};$('allTab').onclick=()=>{showAll=true;$('allTab').classList.add('active');$('selectedTab').classList.remove('active');ranking()};$('closeDrawer').onclick=()=>{$('drawer').classList.remove('open');$('drawer').setAttribute('aria-hidden','true')};$('drawer').onclick=e=>{if(e.target===$('drawer'))$('closeDrawer').click()};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('closeDrawer').click()});load().catch(e=>$('decisionSummary').innerHTML=`<div class="notice">Dashboard unavailable: ${esc(e.message)}</div>`);
</script></body></html>'''
